using namespace hanmo::resident;
namespace {int checks=0;void check(bool x,const char* why){++checks;if(!x)throw std::runtime_error(why);}void good(Status s){if(!s.ok)throw std::runtime_error(s.error.original.code+":"+s.error.original.path);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code+":"+r.error.original.path);return std::move(r.value);}}
int main(){try{
 auto common_catalog=std::make_shared<CommonCatalog>();CommonState seed;seed.next_instance_id=1;seed.identity.tick=0;WalletView wallet;wallet.id="funds";wallet.balance=73;seed.wallets.insert(wallet.id,wallet);InventoryView inventory;inventory.id="store";inventory.capacity=100;seed.inventories.insert(inventory.id,inventory);CommonStore common(seed,common_catalog);
 MilitaryCatalog cat;cat.military=true;cat.march_condition_model=true;cat.officer_assignment_policy=MilitaryOfficerAssignmentPolicy{};cat.field_command_policy=MilitaryFieldCommandPolicy{};cat.command_shock_policy=MilitaryCommandShockRule{};cat.recovery_policy=MilitaryRecoveryPolicy{};cat.recovery_policy->garrison_ids={"camp"};cat.garrison_rest_policy=MilitaryGarrisonRestPolicy{};cat.garrison_rest_policy->garrison_ids={"camp"};GarrisonDefinition camp;camp.id="camp";camp.organization_id="org";camp.food_item_id="grain";camp.ration_per_person=1;MilitaryUnitDefinition definition;definition.id="unit";definition.commander_actor_id="captain";definition.initial_soldiers=2;definition.initial_training=30;definition.initial_fatigue=25;camp.units={definition};cat.garrisons={camp};MilitaryState military;MilitaryUnitRecord unit;unit.id="unit";unit.source_garrison_id=unit.garrison_id="camp";unit.organization_id="org";unit.commander_actor_id="captain";unit.training=30;unit.fatigue=25;unit.training_action_id=StableId{};unit.member_ids={"soldier:unit:1","soldier:unit:2"};unit.fit=unit.member_ids;military.military_units={unit};
 std::optional<DynamicStepInput> active;MilitaryAccess access;access.rosters_before=[&](const std::vector<StableId>& ids,Integer tick,const StableId& boundary){return active?military_rosters_before(common,military,cat,ids,tick,boundary,*active):military_rosters_before(common,military,cat,ids,tick,boundary);};
 const auto initial_common=common;const auto initial_military=military;
 auto supply=[&](Integer shortage){MilitarySupplyFact f;f.id=take(common.next_id("military"));f.tick=common.tick()+1;f.garrison_id="camp";f.organization_id="org";f.item_id="grain";f.mouth_ids=unit.member_ids;f.required=2;f.shortage=shortage;f.consumed=2-shortage;good(common.append_fact({f.id,"military_supply","military"}));military.supply_facts.push_back(f);return f.id;};
 auto step=[&](Integer shortage){supply(shortage);active=DynamicStepInput{common.tick(),common.tick()+1,{},{},{}};const auto count=military.garrison_rest.facts.size();auto effects=take(step_military_garrison_rest(common,military,cat,access,*active));good(validate_military_garrison_rest_history(common,military,cat,access,&*active));if(!effects.empty()){check(!validate_military_garrison_rest_history(common,military,cat,access).ok,"stable reader rejects preclock result");check(!step_military_garrison_rest(common,military,cat,access,*active).ok,"same committed step cannot award twice");}++common.state().identity.tick;active.reset();good(validate_military_garrison_rest_history(common,military,cat,access));auto folded=take(fold_military_condition(military,cat,"unit",common.tick()));check(folded.fatigue==*military.military_units[0].fatigue&&folded.training==30,"current condition exactly follows permanent sources");check(military.military_units[0].fit==unit.fit&&military.military_units[0].wounded.empty()&&common.wallet("funds")->balance==73&&common.inventory("store")->lots.empty(),"rest preserves personnel and assets");return military.garrison_rest.facts.size()-count;};
 check(step(0)==1&&*military.military_units[0].fatigue==15,"first actual qualified halfday reduces ten");check(step(1)==0&&*military.military_units[0].fatigue==15,"shortage earns no rest and cannot catch up later");
 {auto old_common=common;auto old_military=military;military.garrison_rest.facts.clear();common.state().facts.erase(old_military.garrison_rest.facts[0].id);check(!validate_military_garrison_rest_history(common,military,cat,access).ok,"deleting actual rest head and payload rejected from supplied periods");common=old_common;military=old_military;}
 // 同半日实际训练事实使休整暂停；此夹具只核训练占用头和起止，完整教学领域另有先验。
 MilitaryTrainingFact training;training.id=take(common.next_id("action"));training.actor_id="captain";training.start_tick=common.tick();training.terms.unit_id="unit";good(common.append_fact({training.id,"military_training","military"}));military.training_facts.push_back(training);check(step(0)==0,"ongoing actual training period cannot also rest");military.training_facts.back().phase="completed";military.training_facts.back().completed_tick=common.tick();check(step(0)==1&&*military.military_units[0].fatigue==5,"following actual free halfday rests");check(step(0)==1&&*military.military_units[0].fatigue==0,"fatigue has a zero floor");check(step(0)==0&&military.garrison_rest.facts.size()==3,"zero fatigue creates no fake work receipt");
 CommonState only_rest;only_rest.next_instance_id=1025;only_rest.facts.insert("military_rest:1024",{"military_rest:1024","military_garrison_rest","military"});auto common_json=encode_common_state(only_rest);auto common_restored=take(decode_common_seed(common_json,*common_catalog,nullptr,CommonSeedValidation::defer_until_bundle));check(common_restored.facts.find("military_rest:1024")->domain=="military"&&common_restored.next_instance_id>1024,"Common boundary preserves exact kind and allocator prefix");
 auto encoded=military_garrison_rest_codec::encode(military.garrison_rest);auto decoded=take(military_garrison_rest_codec::decode(encoded));check(decoded.facts.size()==3,"JSON keeps exact actual periods");auto bad=encoded;bad.as<BoundaryValue::Dict>()->push_back(bad.as<BoundaryValue::Dict>()->front());check(!military_garrison_rest_codec::decode(bad).ok,"duplicate JSON root rejected");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);writer.schema_features=military_garrison_rest_checkpoint_feature|military_command_shock_checkpoint_feature;good(military_garrison_rest_codec::visit(writer,decoded));good(writer.finish());MilitaryGarrisonRestState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));reader.schema_features=writer.schema_features;good(military_garrison_rest_codec::visit(reader,restored));good(reader.finish());check(restored.facts.size()==3&&restored.facts[0].supply_fact_id==decoded.facts[0].supply_fact_id,"typed roundtrip retains exact supply source");CodecVisitor::Buffer old;CodecVisitor old_writer(old);old_writer.schema_features=military_command_shock_checkpoint_feature;check(!military_garrison_rest_codec::visit(old_writer,restored).ok,"old11 cannot hide a new12 section");
 auto original=military;military.garrison_rest.facts[1].supply_fact_id=military.garrison_rest.facts[0].supply_fact_id;check(!validate_military_garrison_rest_history(common,military,cat,access).ok,"same old food cannot fund later rest");military=original;military.garrison_rest.facts[0].organization_id="enemy";check(!validate_military_garrison_rest_history(common,military,cat,access).ok,"current or invented owner cannot rewrite old supplied entitlement");military=original;
 // 原候选已写疲劳后才分配末回执失败；这里验证显式保存/恢复，不冒World事务调度通过。
 common=initial_common;military=initial_military;common.state().next_instance_id=std::numeric_limits<Integer>::max()-2;supply(0);active=DynamicStepInput{0,1,{},{},{}};const auto before_common=common;const auto before_military=military;auto committed=take(step_military_garrison_rest(common,military,cat,access,*active));check(committed.size()==1&&*military.military_units[0].fatigue==15,"actual condition write precedes forced late result failure");check(!common.next_id("result").ok,"late result allocator fails");common=before_common;military=before_military;check(*military.military_units[0].fatigue==25&&military.garrison_rest.facts.empty()&&common.wallet("funds")->balance==73&&military.military_units[0].fit==unit.fit,"outer candidate restoration retains condition personnel and assets");active.reset();
 check(!validate_military_garrison_rest_modules({{military_garrison_rest_module,"1"}}).ok,"new12 requires actual11 chain");check(!validate_military_garrison_rest_modules({{military_garrison_rest_module,"2"}}).ok,"future marker rejects");
 std::cout<<"MILITARY_GARRISON_REST="<<checks<<" FAILURES=0 SCOPE=TYPED_SOURCE_COMPONENT\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_GARRISON_REST_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
